package com.maganimata.app;

import android.app.*;import android.os.Bundle;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.Gravity;import android.view.View;import android.widget.*;import org.json.JSONObject;import java.util.*;

public class AuthActivity extends Activity {
 private final int PRIMARY=Color.rgb(201,67,128), DARK=Color.rgb(48,39,46), MUTED=Color.rgb(112,101,110); private LinearLayout root,form; private EditText name,email,password; private TextView title,subtitle,switcher,status; private boolean register=false;
 private int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);} private TextView tv(String s,float z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);t.setTypeface(null,b?Typeface.BOLD:Typeface.NORMAL);return t;} private GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
 @Override public void onCreate(Bundle b){super.onCreate(b);build();}
 private void build(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(30),dp(22),dp(22));root.setBackgroundColor(0xFFFFF8FC);TextView logo=tv("♡",52,Color.WHITE,true);logo.setGravity(Gravity.CENTER);logo.setBackground(bg(PRIMARY,24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(88),dp(88));lp.gravity=Gravity.CENTER_HORIZONTAL;root.addView(logo,lp);title=tv("Welcome to Lafiyar Mace",25,DARK,true);title.setGravity(Gravity.CENTER);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.setMargins(0,dp(20),0,dp(4));root.addView(title,tp);subtitle=tv("Create an account to use trackers, comments and Ask a Doctor.",14,MUTED,false);subtitle.setGravity(Gravity.CENTER);root.addView(subtitle);ScrollView sc=new ScrollView(this);form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(0,dp(18),0,dp(20));sc.addView(form);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);renderForm();}
 private EditText field(String hint,boolean pass){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(15);e.setSingleLine(true);e.setPadding(dp(15),dp(8),dp(15),dp(8));e.setTextColor(DARK);e.setHintTextColor(0xFF9A8F97);e.setBackground(bg(0xFFFFFFFF,15));if(pass)e.setInputType(0x81);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,0,0,dp(12));form.addView(e,p);return e;}
 private void renderForm(){form.removeAllViews();if(register)name=field("Full name",false);email=field("Email address",false);email.setInputType(0x21);password=field("Password (6+ characters)",true);Button submit=new Button(this);submit.setText(register?"CREATE ACCOUNT":"LOGIN");submit.setTextColor(Color.WHITE);submit.setTextSize(15);submit.setTypeface(null,Typeface.BOLD);submit.setBackground(bg(PRIMARY,15));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(52));sp.setMargins(0,dp(5),0,dp(12));form.addView(submit,sp);submit.setOnClickListener(v->submit());status=tv("",13,0xFF9B2D3E,false);status.setPadding(dp(5),0,dp(5),dp(8));form.addView(status);
  if(!register){TextView forgot=tv("Forgot password?",14,PRIMARY,true);forgot.setGravity(Gravity.CENTER);form.addView(forgot,new LinearLayout.LayoutParams(-1,dp(42)));forgot.setOnClickListener(v->forgotDialog());}
  switcher=tv(register?"Already have an account? Login":"Don't have an account? Register",14,PRIMARY,true);switcher.setGravity(Gravity.CENTER);form.addView(switcher,new LinearLayout.LayoutParams(-1,dp(48)));switcher.setOnClickListener(v->{register=!register;renderForm();});}
 private void submit(){String n=register&&name!=null?name.getText().toString().trim():"",em=email.getText().toString().trim(),pw=password.getText().toString();if(register&&n.isEmpty()){status.setText("Enter your name.");return;}if(em.isEmpty()||pw.isEmpty()){status.setText("Enter your email and password.");return;}if(register&&pw.length()<6){status.setText("Password must be at least 6 characters.");return;}status.setText("Please wait...");Map<String,String>m=new HashMap<>();m.put("action",register?"register":"login");m.put("email",em);m.put("password",pw);if(register)m.put("name",n);Api.post("auth.php",m,"",new Api.Callback(){public void ok(String body){runOnUiThread(()->handleAuthResponse(body));}public void err(Exception e){runOnUiThread(()->status.setText(apiErrorMessage(e)));}});}
 private void handleAuthResponse(String body){try{String clean=body==null?"":body.trim();JSONObject r=new JSONObject(clean);if(!r.optBoolean("ok")){status.setText(r.optString("error","Unable to continue."));return;}JSONObject u=r.optJSONObject("user");String tok=r.optString("token","");if(tok.isEmpty()||u==null){status.setText("Server returned an incomplete login response.");return;}getSharedPreferences("magani_prefs",MODE_PRIVATE).edit().putString("auth_token",tok).putInt("user_id",u.optInt("id",0)).putString("user_name",u.optString("name","")).putString("user_email",u.optString("email","")).apply();setResult(RESULT_OK);finish();}catch(Exception e){String raw=body==null?"":body.trim();if(raw.length()>220)raw=raw.substring(0,220)+"…";status.setText("Invalid server response: "+raw);}}
 private String apiErrorMessage(Exception e){
  if(e==null) return "Server connection failed.";
  String msg=e.getMessage();
  if(msg==null || msg.trim().isEmpty()) msg=e.getClass().getSimpleName();
  msg=msg.replace("java.net.","");
  if(msg.length()>220) msg=msg.substring(0,220)+"…";
  return "Server error: "+msg;
 }

 private void forgotDialog(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(4),dp(4),dp(4),dp(4));EditText em=fieldIn(l,"Email address");new AlertDialog.Builder(this).setTitle("Forgot password").setMessage("We will send a 6-digit reset code to your email.").setView(l).setNegativeButton("Cancel",null).setPositiveButton("SEND CODE",(d,w)->requestReset(em.getText().toString().trim())).show();}
 private EditText fieldIn(LinearLayout l,String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setInputType(0x21);e.setPadding(dp(14),dp(8),dp(14),dp(8));e.setTextColor(DARK);e.setHintTextColor(0xFF9A8F97);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,dp(56));fp.setMargins(0,0,0,dp(10));l.addView(e,fp);return e;}
 private void requestReset(String em){if(em.isEmpty()){status.setText("Enter your email.");return;}Map<String,String>m=new HashMap<>();m.put("action","request_reset");m.put("email",em);Api.post("auth.php",m,"",new Api.Callback(){public void ok(String b){runOnUiThread(()->{try{JSONObject r=new JSONObject(b);if(!r.optBoolean("ok")){status.setText(r.optString("error","Unable to send code."));return;}status.setText(r.optString("message","If the email is registered, a code was sent."));resetDialog(em);}catch(Exception e){status.setText("Invalid server response.");}});}public void err(Exception e){runOnUiThread(()->status.setText(apiErrorMessage(e)));}});}
 private void resetDialog(String em){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(4),dp(4),dp(4),dp(4));EditText code=fieldIn(l,"6-digit code");EditText pw=fieldIn(l,"New password (6+ characters)");pw.setInputType(0x81);new AlertDialog.Builder(this).setTitle("Reset password").setMessage("Enter the code sent to "+em).setView(l).setNegativeButton("Cancel",null).setPositiveButton("RESET PASSWORD",(d,w)->doReset(em,code.getText().toString().trim(),pw.getText().toString())).show();}
 private void doReset(String em,String code,String pw){Map<String,String>m=new HashMap<>();m.put("action","reset_password");m.put("email",em);m.put("code",code);m.put("password",pw);Api.post("auth.php",m,"",new Api.Callback(){public void ok(String b){runOnUiThread(()->{try{JSONObject r=new JSONObject(b);status.setText(r.optString("message",r.optBoolean("ok")?"Password reset successfully.":"Unable to reset password."));if(r.optBoolean("ok")){register=false;renderForm();email.setText(em);}}catch(Exception e){status.setText("Invalid server response.");}});}public void err(Exception e){runOnUiThread(()->status.setText(apiErrorMessage(e)));}});}
}
